"use client";

import { useState, type ComponentType, type SVGProps } from "react";
import { BashDark, Bun, CSSNew, HTML5, JSON as JsonIcon, JavaScript, NPM, PnpmDark, Python, ReactDark, TypeScript, Yarn } from "@ridemountainpig/svgl-react";
import posthog from "posthog-js/full/no-external";
import { Check, Copy, FileCode } from "lucide-react";
import hljs from "highlight.js/lib/core";
import javascript from "highlight.js/lib/languages/javascript";
import typescript from "highlight.js/lib/languages/typescript";
import bash from "highlight.js/lib/languages/bash";
import json from "highlight.js/lib/languages/json";
import css from "highlight.js/lib/languages/css";
import xml from "highlight.js/lib/languages/xml";
import python from "highlight.js/lib/languages/python";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "./tabs";
import "./code-block.css";

hljs.registerLanguage("javascript", javascript);
hljs.registerLanguage("typescript", typescript);
hljs.registerLanguage("bash", highlighter => {
  const grammar = bash(highlighter);
  return {
    ...grammar,
    contains: [
      { scope: "built_in", match: /\b(?:bun|bunx|npm|npx|pnpm|yarn)\b/ },
      { scope: "string", match: /https?:\/\/[^\s"'<>]+/ },
      ...(grammar.contains ?? []),
    ],
  };
});
hljs.registerLanguage("json", json);
hljs.registerLanguage("css", css);
hljs.registerLanguage("xml", xml);
hljs.registerLanguage("python", python);

const managerIcons = { bun: Bun, npm: NPM, pnpm: PnpmDark, yarn: Yarn };
const languageIcons: Record<string, ComponentType<SVGProps<SVGSVGElement>>> = {
  javascript: JavaScript, js: JavaScript,
  typescript: TypeScript, ts: TypeScript,
  jsx: ReactDark, tsx: ReactDark,
  bash: BashDark, sh: BashDark, shell: BashDark,
  css: CSSNew, html: HTML5, xml: HTML5,
  json: JsonIcon, python: Python, py: Python,
};

const isPostHogConfigured = Boolean(
  process.env.NEXT_PUBLIC_POSTHOG_KEY && process.env.NEXT_PUBLIC_POSTHOG_HOST,
);

interface CodeBlockProps {
  code?: string;
  language?: string;
  filename?: string;
  showLineNumbers?: boolean;
  commands?: Record<"bun" | "npm" | "pnpm" | "yarn", string>;
  packageManager?: "bun" | "npm" | "pnpm" | "yarn";
  onPackageManagerChange?: (manager: "bun" | "npm" | "pnpm" | "yarn") => void;
  className?: string;
}

export function CodeBlock({ code = 'const greeting = "Hello, world!";\nconsole.log(greeting);', language = "javascript", filename = "", showLineNumbers = false, commands, packageManager, onPackageManagerChange, className = "" }: CodeBlockProps = {}) {
  const [manager, setManager] = useState<"bun" | "npm" | "pnpm" | "yarn">("bun");
  const selectedManager = packageManager ?? manager;
  const displayedCode = commands ? commands[selectedManager] : code;
  const displayedLanguage = commands ? "bash" : language;
  const [copyResult, setCopyResult] = useState<{ code: string; success: boolean }>();
  const currentResult = copyResult?.code === displayedCode ? copyResult : undefined;

  async function copyCode() {
    try {
      await navigator.clipboard.writeText(displayedCode);
      setCopyResult({ code: displayedCode, success: true });
      if (isPostHogConfigured) {
        posthog.capture("code_copied", {
          content_type: commands ? "installation_command" : "source_code",
          language: displayedLanguage,
          package_manager: commands ? selectedManager : undefined,
        });
      }
    } catch {
      setCopyResult({ code: displayedCode, success: false });
    }
  }

  const header = <CodeBlockHeader commands={Boolean(commands)} language={displayedLanguage} filename={filename} copied={currentResult?.success} onCopy={copyCode} />;
  const content = <CodeBlockContent code={displayedCode} language={displayedLanguage} filename={filename} showLineNumbers={showLineNumbers} packageManager={commands ? selectedManager : undefined} />;

  return (
    <div className={`lazy-code-block w-full min-w-0 border border-border bg-card text-card-foreground ${className}`}>
      {commands ? <Tabs value={selectedManager} onValueChange={value => {
        const next = value as keyof typeof managerIcons;
        setManager(next);
        onPackageManagerChange?.(next);
      }} className="gap-0">
        {header}
        {(["bun", "npm", "pnpm", "yarn"] as const).map(option => (
          <TabsContent key={option} value={option}>
            {selectedManager === option ? content : null}
          </TabsContent>
        ))}
      </Tabs> : <>{header}{content}</>}
      <span role="status" className={currentResult && !currentResult.success ? "block border-t border-border px-4 py-2 text-xs text-muted-foreground" : "sr-only"}>{currentResult?.success ? "Code copied to clipboard." : currentResult ? "Could not copy. Select the code and copy it manually." : ""}</span>
    </div>
  );
}

function CodeBlockHeader({ commands, language, filename, copied, onCopy }: { commands: boolean; language: string; filename: string; copied?: boolean; onCopy: () => void }) {
  const LanguageIcon = languageIcons[language.toLowerCase()] ?? FileCode;
  return (
      <div className="flex items-center justify-between gap-3 border-b border-border px-4 py-2">
        {commands ? <TabsList aria-label="Package manager">
          {(["bun", "npm", "pnpm", "yarn"] as const).map(option => {
            const ManagerIcon = managerIcons[option];
            return <TabsTrigger key={option} value={option}><ManagerIcon width={16} height={16} aria-hidden="true" focusable="false" className="shrink-0" />{option}</TabsTrigger>;
          })}
        </TabsList> : <span className="flex min-w-0 items-center gap-2 font-mono text-xs text-muted-foreground"><LanguageIcon width={16} height={16} aria-hidden="true" focusable="false" className="shrink-0" /><span className="truncate">{filename || language || "Code"}</span></span>}
        <button type="button" aria-label="Copy code" title={copied ? "Copied!" : "Copy code"} onClick={onCopy} className="inline-flex size-9 shrink-0 items-center justify-center hover:bg-muted focus-visible:outline-2 focus-visible:outline-ring">{copied ? <Check size={16} aria-hidden="true" /> : <Copy size={16} aria-hidden="true" />}</button>
      </div>
  );
}

function CodeBlockContent({ code, language, filename, showLineNumbers, packageManager }: { code: string; language: string; filename: string; showLineNumbers: boolean; packageManager?: string }) {
  const highlighted = hljs.getLanguage(language)
    ? hljs.highlight(code, { language, ignoreIllegals: true }).value : undefined;
  return (
      <pre tabIndex={0} aria-label={filename ? `Code from ${filename}` : packageManager ? `${packageManager} installation command` : `${language || "Plain text"} code`} className="flex max-w-full gap-4 overflow-x-auto p-4 font-mono text-sm leading-6 focus-visible:outline-2 focus-visible:outline-ring">
        {showLineNumbers && <span aria-hidden="true" className="select-none text-right text-muted-foreground">{code.split("\n").map((_, index) => index + 1).join("\n")}</span>}
        {highlighted === undefined ? <code>{code}</code> : <code className={`hljs language-${language}`} dangerouslySetInnerHTML={{ __html: highlighted }} />}
      </pre>
  );
}

.lazy-code-block .hljs { color: var(--card-foreground); }
.lazy-code-block .hljs-comment,
.lazy-code-block .hljs-quote { color: var(--muted-foreground); font-style: italic; }
.lazy-code-block .hljs-keyword,
.lazy-code-block .hljs-selector-tag,
.lazy-code-block .hljs-tag { color: var(--primary); }
.lazy-code-block .hljs-string,
.lazy-code-block .hljs-attr,
.lazy-code-block .hljs-template-tag { color: var(--info); }
.lazy-code-block .hljs-number,
.lazy-code-block .hljs-literal { color: var(--warning); }
.lazy-code-block .hljs-built_in { color: var(--primary); }
.lazy-code-block .hljs-title,
.lazy-code-block .hljs-name,
.lazy-code-block .hljs-type { color: var(--card-foreground); }

"use client";

import { createContext, useContext, useId, useState, useCallback, useMemo, type ComponentProps } from "react";
import { cn } from "cn";

interface TabsProps extends Omit<ComponentProps<"div">, "defaultValue" | "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: "horizontal" | "vertical";
}

const TabsContext = createContext<{
  id: string;
  value?: string;
  orientation: "horizontal" | "vertical";
  select: (value: string) => void;
} | null>(null);

function useTabs() {
  const context = useContext(TabsContext);
  if (!context) throw new Error("Tabs components must be rendered inside Tabs.");
  return context;
}

export function Tabs({ className, value, defaultValue, onValueChange, orientation = "horizontal", children, ...props }: TabsProps) {
  const id = useId();
  const [selected, setSelected] = useState(defaultValue);
  const select = useCallback((next: string) => {
    if (value === undefined) setSelected(next);
    onValueChange?.(next);
  }, [value, onValueChange]);
  const context = useMemo(() => ({ id, value: value ?? selected, orientation, select }), [id, value, selected, orientation, select]);
  return (
    <TabsContext.Provider value={context}>
      <div {...props} data-slot="tabs" data-orientation={orientation} className={cn("group/tabs flex w-full gap-2 data-[orientation=horizontal]:flex-col", className)}>
        {children}
      </div>
    </TabsContext.Provider>
  );
}

function tabsListVariants({ variant = "default" }: { variant?: "default" | "line" } = {}) {
  return cn(
    "group/tabs-list inline-flex w-fit items-center justify-center p-1 text-muted-foreground group-data-[orientation=vertical]/tabs:h-fit group-data-[orientation=vertical]/tabs:flex-col",
    variant === "line" ? "gap-1 bg-transparent" : "bg-muted",
  );
}

export function TabsList({ className, variant = "default", onKeyDown, ...props }: ComponentProps<"div"> & { variant?: "default" | "line" }) {
  const { orientation } = useTabs();
  return (
    <div {...props} role="tablist" aria-orientation={orientation} data-slot="tabs-list" data-variant={variant} className={cn(tabsListVariants({ variant }), className)} onKeyDown={event => {
      onKeyDown?.(event);
      if (event.defaultPrevented) return;
      const tabs = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="tab"]:not(:disabled)')].filter(tab => tab.closest('[role="tablist"]') === event.currentTarget);
      const index = tabs.indexOf(event.target as HTMLButtonElement);
      if (index < 0) return;
      const forward = orientation === "horizontal" ? "ArrowRight" : "ArrowDown";
      const backward = orientation === "horizontal" ? "ArrowLeft" : "ArrowUp";
      const next = event.key === "Home" ? tabs[0] : event.key === "End" ? tabs.at(-1)
        : event.key === forward ? tabs[(index + 1) % tabs.length]
        : event.key === backward ? tabs[(index - 1 + tabs.length) % tabs.length] : undefined;
      if (!next) return;
      event.preventDefault();
      next.focus();
      next.click();
    }} />
  );
}

export function TabsTrigger({ className, value, disabled, onClick, ...props }: Omit<ComponentProps<"button">, "value"> & { value: string }) {
  const tabs = useTabs();
  const active = !disabled && tabs.value === value;
  const key = encodeURIComponent(value);
  return (
    <button {...props} type="button" role="tab" id={`${tabs.id}-tab-${key}`} aria-controls={`${tabs.id}-panel-${key}`} aria-selected={active} disabled={disabled} tabIndex={active || tabs.value === undefined && !disabled ? 0 : -1} data-slot="tabs-trigger" data-active={active ? "" : undefined}
      className={cn(
        "relative inline-flex min-h-8 flex-1 items-center justify-center gap-1.5 border border-border px-3 py-1 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 group-data-[orientation=vertical]/tabs:w-full group-data-[orientation=vertical]/tabs:justify-start",
        "data-active:bg-background data-active:text-foreground group-data-[variant=line]/tabs-list:border-transparent group-data-[variant=line]/tabs-list:data-active:bg-transparent after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-[variant=line]/tabs-list:data-active:after:opacity-100 group-data-[orientation=horizontal]/tabs:after:inset-x-0 group-data-[orientation=horizontal]/tabs:after:-bottom-1 group-data-[orientation=horizontal]/tabs:after:h-0.5 group-data-[orientation=vertical]/tabs:after:inset-y-0 group-data-[orientation=vertical]/tabs:after:-right-1 group-data-[orientation=vertical]/tabs:after:w-0.5",
        className,
      )} onClick={event => {
        onClick?.(event);
        if (!event.defaultPrevented && !disabled) tabs.select(value);
      }} />
  );
}

export function TabsContent({ className, value, ...props }: ComponentProps<"div"> & { value: string }) {
  const tabs = useTabs();
  const key = encodeURIComponent(value);
  return <div {...props} role="tabpanel" id={`${tabs.id}-panel-${key}`} aria-labelledby={`${tabs.id}-tab-${key}`} hidden={tabs.value !== value} tabIndex={0} data-slot="tabs-content" className={cn("min-w-0 flex-1 text-sm leading-6 focus-visible:outline-2 focus-visible:outline-ring", className)} />;
}
